import {useEffect,useState, type FormEvent, type ReactNode} from 'react';
import {LayoutDashboard,CarFront,UsersRound,CalendarDays,FileText,Receipt,Settings,Plus,ArrowUpRight,ArrowRight,Search,ChevronLeft,ChevronRight,Check, X, Menu,Wallet,Clock3,TriangleAlert,Printer,Pencil,Trash2,RotateCcw,Download,CheckCircle2} from 'lucide-react';
import {type Data,type Car,type Client,type Booking,type Contract,type Invoice,type Inspection,seed,load,STORAGE_KEY,uid,relative,localDate,date,money,days,total,subtotal,paid,balance,clientName,carName,statusOf,availability,paymentError,returnError} from './domain';
import DashboardPlanning from './DashboardPlanning';
import CarDrawing from './CarDrawing';
type View='Tableau de bord'|'Voitures'|'Clients'|'Réservations'|'Contrats'|'Factures'|'Paramètres';
type Modal={kind:string;id?:string;extra?:string}|null;
const nav=[['Tableau de bord',LayoutDashboard],['Voitures',CarFront],['Clients',UsersRound],['Réservations',CalendarDays],['Contrats',FileText],['Factures',Receipt]] as const;
const Badge=({children}:{children:ReactNode})=><span className={`badge ${String(children).replaceAll(' ','-')}`}>{children}</span>;
const Empty=({text='Aucun élément à afficher.'}:{text?:string})=><div className="empty"><CalendarDays size={32}/><p>{text}</p></div>;
function Field({label,name,value='',type='text',required=false,min,step,options}:{label:string;name:string;value?:string|number;type?:string;required?:boolean;min?:number;step?:string;options?:{value:string;label:string}[]}){return <label className="field"><span>{label}{required?' *':''}</span>{options?<select name={name} defaultValue={value} required={required}>{options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:type==='textarea'?<textarea name={name} defaultValue={value} rows={3}/>:<input name={name} type={type} defaultValue={value} required={required} min={min} step={step} accept={type==='file'?'image/*':undefined}/>}</label>}
const photoRead=async(file:FormDataEntryValue|null):Promise<string>=>{if(!(file instanceof File)||!file.size)return '';if(!file.type.startsWith('image/'))throw new Error('Choisissez un fichier image.');if(file.size>1500000)throw new Error('Choisissez une image de moins de 1,5 Mo pour la sauvegarde locale.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('Lecture de l’image impossible.'));reader.readAsDataURL(file)});};
function initial(){try{return {data:load(),error:''}}catch{return {data:null,error:'Les données enregistrées ne peuvent pas être lues. Exportez-les avant de réinitialiser la démo.'}}}
export default function App(){
 const [start]=useState(initial);const [data,setData]=useState<Data>(start.data??seed());const [fatal,setFatal]=useState(start.error);const [view,setView]=useState<View>('Tableau de bord');const [modal,setModal]=useState<Modal>(null);const [toast,setToast]=useState('');const [error,setError]=useState('');const [query,setQuery]=useState('');const [mobile,setMobile]=useState(false);const [calendar,setCalendar]=useState(false);const [month,setMonth]=useState(new Date());const [filter,setFilter]=useState('Tous');const [from,setFrom]=useState('');const [to,setTo]=useState('');const [printDoc,setPrintDoc]=useState<{contract:Contract;invoice?:Invoice}|null>(null);
 const agencyName=data.agency.name.trim()||'Gestion Location Auto';
 const agencyInitials=agencyName.split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase();
 useEffect(()=>{document.title=`${agencyName} — Gestion de location`},[agencyName]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(!fatal&&!localStorage.getItem(STORAGE_KEY))try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data))}catch{setFatal('La sauvegarde locale est indisponible. Autorisez le stockage dans ce navigateur.')}},[]);
 useEffect(()=>{setError('')},[modal]);
 useEffect(()=>{if(!modal)return;const prior=document.activeElement as HTMLElement;const t=setTimeout(()=>document.querySelector<HTMLElement>('.modal input, .modal select, .modal button')?.focus(),30);const handle=(e:KeyboardEvent)=>{if(e.key==='Escape')setModal(null);if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll<HTMLElement>('.modal button,.modal input,.modal select,.modal textarea')).filter(e=>!e.hasAttribute('disabled'));const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',handle);return()=>{clearTimeout(t);document.removeEventListener('keydown',handle);prior?.focus()}},[modal]);
 function save(next:Data,message='Enregistré avec succès.'){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));setData(next);setToast(message);setError('');return true}catch{setError('Sauvegarde impossible : le stockage est plein ou bloqué. Essayez une photo plus petite.');return false}}
 function update(fn:(d:Data)=>void,message?:string){const next=structuredClone(data);fn(next);return save(next,message)}
 function go(v:View){setView(v);setQuery('');setFilter('Tous');setMobile(false)}
 function open(kind:string,id?:string,extra?:string){setError('');setModal({kind,id,extra})}
 const car=(id:string)=>data.cars.find(x=>x.id===id);const client=(id:string)=>data.clients.find(x=>x.id===id);const contract=(id:string)=>data.contracts.find(x=>x.id===id)!;const invoiceFor=(id:string)=>data.invoices.find(x=>x.contractId===id);
 const today=localDate();const active=data.contracts.filter(c=>c.status!=='annulé');const receipts=active.reduce((s,c)=>s+paid(c),0);const outstanding=active.reduce((s,c)=>s+balance(c),0);
 const late=data.contracts.filter(c=>c.status==='en cours'&&new Date(c.end)<new Date());
 const alerts=data.cars.flatMap(c=>[{when:c.insurance,label:'Assurance à renouveler'},{when:c.inspection,label:'Visite technique'},{when:c.oilDate,label:'Vidange à prévoir'}].filter(x=>x.when&&new Date(x.when).getTime()<Date.now()+30*86400000).map(x=>({car:c,label:x.label,when:x.when})).concat(c.km>=c.oilKm&&c.oilKm>0?[{car:c,label:'Kilométrage de vidange atteint',when:today}]:[]));
 const match=(s:string)=>s.toLocaleLowerCase().includes(query.toLocaleLowerCase());
 function generate(c:Contract){const existing=invoiceFor(c.id);if(existing){open('invoice',existing.id);return}const next=structuredClone(data);next.counters.invoice++;const inv:Invoice={id:uid(),number:`FAC-${new Date().getFullYear()}-${String(next.counters.invoice).padStart(4,'0')}`,contractId:c.id,date:today,agency:structuredClone(data.agency),client:structuredClone(client(c.clientId)!),car:structuredClone(car(c.carId)!),contract:structuredClone(c)};next.invoices.push(inv);if(save(next,'Facture créée et liée au contrat.'))open('invoice',inv.id)}
 function convert(b:Booking){const conflict=availability(data,b.carId,b.start,b.end,b.id);if(conflict){setError(conflict);return}const next=structuredClone(data);next.counters.contract++;const c=makeContract(next,b);next.contracts.push(c);next.bookings.find(x=>x.id===b.id)!.status='convertie en contrat';if(save(next,'Réservation convertie en contrat.'))open('contract',c.id)}
 function makeContract(d:Data,b:Pick<Booking,'carId'|'clientId'|'start'|'end'|'rate'> & {id?:string}):Contract{return {id:uid(),number:`CTR-${new Date().getFullYear()}-${String(d.counters.contract).padStart(4,'0')}`,bookingId:b.id,carId:b.carId,clientId:b.clientId,start:b.start,end:b.end,rate:b.rate,discount:0,tax:d.agency.taxEnabled?d.agency.taxRate:0,driver:`${client(b.clientId)?.first??''} ${client(b.clientId)?.last??''}`,notes:'',conditions:d.agency.conditions,status:'préparé',payments:[],depositExpected:3000,depositReceived:0,depositReturned:0,depositLog:[],fees:[]}}
 function print(c:Contract,inv?:Invoice){setPrintDoc({contract:c,invoice:inv});setTimeout(()=>window.print(),120)}
 function downloadBackup(){const blob=new Blob([localStorage.getItem(STORAGE_KEY)??JSON.stringify(data)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`atlas-sauvegarde-${today}.json`;a.click();URL.revokeObjectURL(url)}
 const table=(headers:string[],rows:ReactNode[])=>rows.length?<div className="table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows}</tbody></table></div>:<Empty/>;
 const rentalRow=(c:Contract)=><tr key={c.id}><td><button className="text-link" onClick={()=>open('contract',c.id)}>{c.number}</button><small>{clientName(client(c.clientId))}</small></td><td>{carName(car(c.carId))}<small>{car(c.carId)?.plate}</small></td><td>{date(c.start)}<small>au {date(c.end)}</small></td><td><Badge>{c.status}</Badge></td><td><b>{money(total(c))}</b><small>{balance(c)>0?`${money(balance(c))} à payer`:'Entièrement payé'}</small></td><td><button className="icon-button" title="Consulter le contrat" onClick={()=>open('contract',c.id)}><ArrowUpRight size={18}/></button></td></tr>;
 const bookingRows=(items:Booking[])=>table(['Client','Voiture','Période','Total','Statut',''],items.map(b=><tr key={b.id}><td><button className="text-link" onClick={()=>open('booking',b.id)}>{clientName(client(b.clientId))}</button></td><td>{carName(car(b.carId))}<small>{car(b.carId)?.plate}</small></td><td>{date(b.start,true)}<small>au {date(b.end,true)}</small></td><td>{money(days(b.start,b.end)*b.rate)}<small>{days(b.start,b.end)} jours</small></td><td><Badge>{b.status}</Badge></td><td><button className="icon-button" title="Consulter la réservation" onClick={()=>open('booking',b.id)}><ArrowUpRight size={18}/></button></td></tr>));
 return <><div className="app-shell"><aside className={mobile?'sidebar show':'sidebar'}><a className="brand" href="#" onClick={e=>{e.preventDefault();go('Tableau de bord')}}><span className="brand-mark">{agencyInitials}</span><span className="brand-name">{agencyName}<span className="brand-sub">GESTION DE LOCATION</span></span></a><div className="workspace"><span className="agency-icon">{agencyInitials}</span><div><b>{agencyName}</b><small>Espace agence</small></div><span className="online"/></div><span className="nav-label">GESTION DE L’AGENCE</span><nav>{nav.map(([label,Icon])=><button key={label} className={view===label?'active':''} onClick={()=>go(label)}><Icon size={20}/>{label}{label==='Réservations'&&<span className="nav-count">{data.bookings.filter(b=>b.status==='confirmée').length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="demo-card"><span className="demo-dot"/> Mode démonstration<small>Données fictives · sauvegarde locale</small></div><button className={view==='Paramètres'?'settings active':'settings'} onClick={()=>go('Paramètres')}><Settings size={19}/>Paramètres de l’agence</button><div className="profile"><span>AD</span><div><b>Administrateur</b><small>Gestion de l’agence</small></div></div></div></aside>{mobile&&<button className="scrim" aria-label="Fermer le menu" onClick={()=>setMobile(false)}/>}
 <main><header className="topbar"><button className="icon-button mobile-menu" aria-label="Menu" onClick={()=>setMobile(!mobile)}><Menu/></button><div className="breadcrumb">Espace agence <span>/</span> <b>{view}</b></div><div className="top-right"><span className="local-indicator"><i/>Enregistré sur cet appareil</span><span className="avatar">AD</span></div></header><div className="page"><div className="page-heading"><div><div className="eyebrow">{agencyName}</div><h1>{view}</h1><p>{view==='Tableau de bord'?new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date()):{Voitures:'Disponibilité, tarifs et suivi des véhicules.',Clients:'Coordonnées, historique et soldes des clients.',Réservations:'Planning et gestion des réservations.',Contrats:'Suivez chaque location du départ au retour.',Factures:'Des documents distincts, liés à vos contrats.',Paramètres:'Les informations qui apparaissent sur vos documents.'}[view]}</p></div><div className="heading-actions">{view==='Tableau de bord'||view==='Réservations'?<button className="primary" onClick={()=>open('bookingForm')}><Plus size={18}/>Nouvelle réservation</button>:view==='Voitures'?<button className="primary" onClick={()=>open('carForm')}><Plus size={18}/>Ajouter une voiture</button>:view==='Clients'?<button className="primary" onClick={()=>open('clientForm')}><Plus size={18}/>Ajouter un client</button>:view==='Contrats'?<button className="primary" onClick={()=>open('contractForm')}><Plus size={18}/>Nouveau contrat</button>:null}</div></div>
 {fatal&&<div className="alert danger">{fatal}<button onClick={downloadBackup}>Exporter les données</button><button onClick={()=>open('reset')}>Réinitialiser</button></div>}
 {view==='Tableau de bord'&&<><div className="stats"><div className="stat"><span>Voitures disponibles <CarFront size={21}/></span><strong>{data.cars.filter(c=>statusOf(data,c)==='disponible').length}<small>/ {data.cars.length}</small></strong><div><i className="dot green"/>Disponibles actuellement</div></div><div className="stat"><span>Voitures en location <ArrowUpRight size={21}/></span><strong>{data.cars.filter(c=>statusOf(data,c)==='louée').length}</strong><div><i className="dot blue"/>Locations en cours</div></div><div className="stat"><span>En maintenance <Settings size={21}/></span><strong>{data.cars.filter(c=>statusOf(data,c)==='maintenance').length}</strong><div><i className="dot orange"/>Indisponibles à la réservation</div></div><div className="stat finance"><span>Encaissements de location <Wallet size={21}/></span><strong>{money(receipts)}</strong><div>Cumul de la démo · hors cautions</div></div></div>
 <div className="dashboard-grid planning-layout">
  <DashboardPlanning data={data} open={open}/>
  <div className="planning-sidebar">
   <section className="panel attention"><div className="section-heading"><h2>À votre attention</h2><span className="alert-count">{late.length+alerts.length}</span></div>{late.map(c=><button key={c.id} className="notice red" onClick={()=>open('contract',c.id)}><Clock3 size={19}/><span><b>Retour en retard</b><small>{carName(car(c.carId))} · prévu le {date(c.end)}</small></span><ChevronRight size={17}/></button>)}{alerts.slice(0,4).map((a,i)=><button key={i} className="notice amber" onClick={()=>open('car',a.car.id)}><TriangleAlert size={19}/><span><b>{a.label}</b><small>{carName(a.car)} · {date(a.when)}</small></span></button>)}{!late.length&&!alerts.length&&<Empty text="Tout est à jour."/>}</section>
   <section className="panel balance-card"><span className="eyebrow">À ENCAISSER</span><h2>{money(outstanding)}</h2><p>Solde des locations non annulées</p><div className="balance-line"><span>Cautions détenues</span><b>{money(active.reduce((s,c)=>s+c.depositReceived-c.depositReturned,0))}</b></div><small>Les cautions ne sont pas du chiffre d’affaires.</small><button onClick={()=>{go('Contrats');setFilter('À payer')}}>Voir les soldes <ArrowRight size={17}/></button></section>
  </div>
 </div></>}

 {view!=='Tableau de bord'&&view!=='Paramètres'&&<div className="toolbar"><div className="search"><Search size={18}/><input aria-label="Rechercher" placeholder={view==='Voitures'?'Rechercher une voiture, une immatriculation…':`Rechercher dans ${view.toLowerCase()}…`} value={query} onChange={e=>setQuery(e.target.value)}/></div>{view==='Réservations'?<div className="toggle"><button className={!calendar?'selected':''} onClick={()=>setCalendar(false)}>Liste</button><button className={calendar?'selected':''} onClick={()=>setCalendar(true)}><CalendarDays size={17}/>Calendrier</button></div>:['Voitures','Contrats','Clients'].includes(view)?<select aria-label="Filtrer" value={filter} onChange={e=>setFilter(e.target.value)}>{(view==='Voitures'?['Tous','disponible','louée','maintenance']:view==='Clients'?['Tous','particulier','entreprise']:['Tous','préparé','en cours','clôturé','annulé','À payer']).map(x=><option key={x}>{x}</option>)}</select>:null}</div>}
 {view==='Voitures'&&<><div className="availability-bar"><CalendarDays size={20}/><b>Disponibilité sur une période</b><label>Départ<input aria-label="Début de disponibilité" type="datetime-local" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Retour<input aria-label="Fin de disponibilité" type="datetime-local" value={to} onChange={e=>setTo(e.target.value)}/></label>{(from||to)&&<button className="icon-button" title="Effacer les dates" onClick={()=>{setFrom('');setTo('')}}><X size={18}/></button>}</div><div className="car-grid">{data.cars.filter(c=>match(`${carName(c)} ${c.plate}`)&&(filter==='Tous'||statusOf(data,c)===filter)).map(c=><article className="car-card" key={c.id}><div className="car-art">{c.photo?<img src={c.photo} alt={carName(c)}/>:<CarDrawing color={['#adc5c0','#d5d1c7','#647e8c'][data.cars.indexOf(c)%3]}/>}<Badge>{statusOf(data,c)}</Badge><span className="car-year">{c.year}</span></div><div className="car-body"><div className="car-title"><h2>{carName(c)}</h2><strong>{money(c.rate)}<small>/ jour</small></strong></div><span className="plate">{c.plate}</span><div className="car-meta"><span>{c.fuel}</span><span>{c.gearbox}</span><span>{c.km.toLocaleString('fr-FR')} km</span></div>{from&&to&&<p className={`availability-result ${availability(data,c.id,from,to)?'unavailable':''}`}>{availability(data,c.id,from,to)||'Disponible pour ces dates'}</p>}<button className="car-detail" onClick={()=>open('car',c.id)}>Voir le véhicule <ArrowUpRight size={17}/></button></div></article>)}</div>{!data.cars.some(c=>match(`${carName(c)} ${c.plate}`)&&(filter==='Tous'||statusOf(data,c)===filter))&&<Empty/>}</>}
 {view==='Clients'&&<section className="panel">{table(['Client','Contact','Permis / entreprise','Locations','Solde',''],data.clients.filter(c=>match(`${clientName(c)} ${c.phone} ${c.identity}`)&&(filter==='Tous'||c.type===filter)).map(c=><tr key={c.id}><td><button className="text-link" onClick={()=>open('client',c.id)}>{clientName(c)}</button><small>{c.type}</small></td><td>{c.phone}<small>{c.email}</small></td><td>{c.type==='entreprise'?`ICE ${c.ice}`:c.license}<small>{c.type==='entreprise'?c.contact:`Expire le ${date(c.licenseExpiry)}`}</small></td><td>{data.contracts.filter(x=>x.clientId===c.id).length}</td><td>{money(active.filter(x=>x.clientId===c.id).reduce((s,x)=>s+balance(x),0))}</td><td><button className="icon-button" title="Voir le client" onClick={()=>open('client',c.id)}><ArrowUpRight size={18}/></button></td></tr>))}</section>}
 {view==='Réservations'&&<><div className="info-line"><Clock3 size={17}/>Chaque tranche de 24 heures commencée compte comme une journée, minimum 1 jour.</div>{calendar?<Calendar month={month} setMonth={setMonth} data={data} query={query} open={open}/>:<section className="panel">{bookingRows(data.bookings.filter(b=>match(`${clientName(client(b.clientId))} ${carName(car(b.carId))}`)).sort((a,b)=>b.start.localeCompare(a.start)))}</section>}</>}
 {view==='Contrats'&&<section className="panel">{table(['Contrat & client','Voiture','Période','Statut','Montant',''],data.contracts.filter(c=>match(`${c.number} ${clientName(client(c.clientId))} ${carName(car(c.carId))}`)&&(filter==='Tous'||filter===c.status||(filter==='À payer'&&c.status!=='annulé'&&balance(c)>0))).slice().reverse().map(rentalRow))}</section>}
 {view==='Factures'&&<><div className="info-line"><Receipt size={18}/>Une facture par contrat. Les paiements sont partagés avec le contrat, sans double comptabilisation.</div><section className="panel">{table(['Facture','Client','Contrat lié','Total','Paiement',''],data.invoices.filter(i=>match(`${i.number} ${clientName(i.client)} ${i.contract.number}`)).slice().reverse().map(i=><tr key={i.id}><td><button className="text-link" onClick={()=>open('invoice',i.id)}>{i.number}</button><small>{date(i.date)}</small></td><td>{clientName(i.client)}</td><td><button className="text-link" onClick={()=>open('contract',i.contractId)}>{i.contract.number}</button></td><td>{money(total(i.contract))}</td><td><Badge>{balance(contract(i.contractId))===0?'payée':'à payer'}</Badge><small>{money(balance(contract(i.contractId)))} restant</small></td><td><button className="icon-button" title="Ouvrir la facture" onClick={()=>open('invoice',i.id)}><ArrowUpRight size={18}/></button></td></tr>))}</section></>}
 {view==='Paramètres'&&<div className="settings-grid"><section className="panel padded"><h2>Informations de l’agence</h2><form onSubmit={submitSettings}><div className="form-grid"><Field label="Nom de l’agence" name="name" value={data.agency.name} required/><Field label="Logo (image, 1,5 Mo maximum)" name="logo" type="file"/><Field label="Adresse" name="address" value={data.agency.address} required/><Field label="Téléphone" name="phone" value={data.agency.phone} required/><Field label="Email" name="email" type="email" value={data.agency.email}/><Field label="ICE (facultatif)" name="ice" value={data.agency.ice}/></div><Field label="Conditions de démonstration" name="conditions" value={data.agency.conditions} type="textarea"/><div className="tax-box"><label><input name="taxEnabled" type="checkbox" defaultChecked={data.agency.taxEnabled}/> Activer une TVA personnalisée</label><Field label="Taux de TVA (%) — à renseigner par l’agence" name="taxRate" type="number" min={0} step="0.01" value={data.agency.taxRate}/><small>Appliqué aux nouveaux contrats seulement. Aucun taux n’est présumé. Ces documents ne sont pas fiscalement validés.</small></div>{error&&<div className="alert danger" role="alert">{error}</div>}<button className="primary" type="submit"><Check size={18}/>Enregistrer les paramètres</button></form></section><section className="panel padded"><h2>Votre espace de démonstration</h2><p className="muted">Les données restent dans ce navigateur. Elles ne sont pas partagées entre appareils.</p><button className="secondary full" onClick={downloadBackup}><Download size={18}/>Exporter une sauvegarde JSON</button><div className="separator"/><h3>Repartir de zéro</h3><p className="muted">Remplace toutes les données par les exemples initiaux, avec des dates actualisées.</p><button className="danger-button" onClick={()=>open('reset')}><RotateCcw size={18}/>Réinitialiser la démo</button></section></div>}
 <footer>{agencyName} <small>Prototype de démonstration</small></footer></div></main></div>
 {toast&&<div className="toast" role="status"><CheckCircle2 size={20}/>{toast}</div>}
 {modal&&<div className="modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(null)}}><section className={`modal ${['contract','invoice','car','client'].includes(modal.kind)?'wide':''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-heading"><h2 id="modal-title">{modalTitle(modal)}</h2><button className="icon-button" aria-label="Fermer" onClick={()=>setModal(null)}><X/></button></div><div className="modal-body">{renderModal()}{error&&<div className="alert danger" role="alert">{error}</div>}</div></section></div>}
 {printDoc&&<div className="print-only"><Document contract={printDoc.contract} data={data} invoice={printDoc.invoice}/></div>}
 </>;
 async function submitSettings(e:FormEvent<HTMLFormElement>){e.preventDefault();try{const f=new FormData(e.currentTarget);const s=(n:string)=>String(f.get(n)??'');const logo=await photoRead(f.get('logo'));const rate=Number(s('taxRate'));if(!Number.isFinite(rate)||rate<0||rate>100)throw new Error('Le taux de TVA doit être compris entre 0 et 100 %.');update(d=>{d.agency={name:s('name'),address:s('address'),phone:s('phone'),email:s('email'),ice:s('ice'),conditions:s('conditions'),logo:logo||d.agency.logo,taxEnabled:f.has('taxEnabled'),taxRate:rate}},'Paramètres enregistrés.')}catch(e){setError((e as Error).message)}}
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!modal)return;const f=new FormData(e.currentTarget);const s=(n:string)=>String(f.get(n)??'').trim();const n=(name:string)=>{const v=Number(s(name));if(!Number.isFinite(v)||v<0)throw new Error('Les montants et kilométrages doivent être positifs ou nuls.');return v};const next=structuredClone(data);try{
 if(modal.kind==='carForm'){
 const old=car(modal.id??'');if(next.cars.some(c=>c.id!==modal.id&&c.plate.replaceAll(' ','').toLowerCase()===s('plate').replaceAll(' ','').toLowerCase()))throw new Error('Cette immatriculation existe déjà.');const status=s('status') as Car['status'];if(status==='maintenance'&&next.contracts.some(c=>c.carId===modal.id&&['préparé','en cours'].includes(c.status))||status==='maintenance'&&next.bookings.some(b=>b.carId===modal.id&&b.status==='confirmée'))throw new Error('Cette voiture a des réservations ou contrats actifs. Annulez-les ou terminez-les avant la mise en maintenance.');
 const image=await photoRead(f.get('photo'));const item:Car={id:old?.id??uid(),brand:s('brand'),model:s('model'),plate:s('plate'),year:n('year'),km:n('km'),photo:image||old?.photo||'',fuel:s('fuel'),gearbox:s('gearbox'),rate:n('rate'),status,insurance:s('insurance'),inspection:s('inspection'),oilDate:s('oilDate'),oilKm:n('oilKm'),maintenance:old?.maintenance??[]};if(old&&item.km<old.km)throw new Error('Le kilométrage ne peut pas diminuer.');if(old)next.cars[next.cars.findIndex(c=>c.id===old.id)]=item;else next.cars.push(item);
 }else if(modal.kind==='clientForm'){
 const old=client(modal.id??'');const item:Client={id:old?.id??uid(),type:s('type') as Client['type'],first:s('first'),last:s('last'),phone:s('phone'),email:s('email'),address:s('address'),identity:s('identity'),license:s('license'),licenseExpiry:s('licenseExpiry'),company:s('company'),ice:s('ice'),contact:s('contact')};if(item.type==='entreprise'&&(!item.company||!/^\d{15}$/.test(item.ice)))throw new Error('Renseignez la raison sociale et un ICE de 15 chiffres.');if(next.clients.some(c=>c.id!==item.id&&c.identity.toLowerCase()===item.identity.toLowerCase()))throw new Error('Un client possède déjà cette CIN ou ce passeport.');if(old)next.clients[next.clients.findIndex(c=>c.id===old.id)]=item;else next.clients.push(item);
 }else if(modal.kind==='bookingForm'||modal.kind==='contractForm'){
 const b={id:modal.id??uid(),carId:s('carId'),clientId:s('clientId'),start:s('start'),end:s('end'),rate:n('rate')};const err=availability(data,b.carId,b.start,b.end,modal.id);if(err)throw new Error(err);if(!client(b.clientId))throw new Error('Choisissez un client.');if(b.rate<=0)throw new Error('Le tarif journalier doit être supérieur à zéro.');if(modal.kind==='bookingForm'){const old=next.bookings.find(x=>x.id===modal.id);if(old){if(old.status!=='confirmée')throw new Error('Cette réservation ne peut plus être modifiée.');Object.assign(old,b)}else next.bookings.push({...b,status:'confirmée'})}else{next.counters.contract++;const c=makeContract(next,{...b,id:undefined});c.discount=n('discount');if(c.discount>days(c.start,c.end)*c.rate)throw new Error('La remise ne peut pas dépasser le prix de location.');c.depositExpected=n('depositExpected');c.driver=s('driver')||c.driver;c.notes=s('notes');next.contracts.push(c);if(save(next,'Contrat créé.'))open('contract',c.id);return}
 }else if(modal.kind==='contractEdit'){
 const c=next.contracts.find(x=>x.id===modal.id)!;if(invoiceFor(c.id))throw new Error('La facture existe déjà : les données financières sont verrouillées.');if(c.status!=='préparé')throw new Error('Seul un contrat préparé peut être modifié.');c.discount=n('discount');c.rate=n('rate');c.depositExpected=n('depositExpected');c.driver=s('driver');c.notes=s('notes');if(c.rate<=0||c.discount>days(c.start,c.end)*c.rate)throw new Error('Le tarif ou la remise est invalide.');if(total(c)<paid(c))throw new Error('Le total ne peut pas être inférieur aux paiements reçus.');if(c.depositExpected<c.depositReceived)throw new Error('La caution attendue ne peut pas être inférieure à la caution déjà reçue.');
 }else if(modal.kind==='payment'){
 const c=next.contracts.find(x=>x.id===modal.id)!;if(c.status==='annulé')throw new Error('Le contrat est annulé.');const amount=n('amount');const err=paymentError(c,amount);if(err)throw new Error(err);if(s('date')>today)throw new Error('La date du paiement ne peut pas être dans le futur.');c.payments.push({id:uid(),date:s('date'),amount,mode:s('mode'),reference:s('reference')});
 }else if(modal.kind==='deposit'){
 const c=next.contracts.find(x=>x.id===modal.id)!;const amount=n('amount');if(amount<=0)throw new Error('Le montant doit être supérieur à zéro.');const receive=s('kind')==='Réception';if(receive&&c.status==='annulé')throw new Error('Le contrat est annulé.');if(receive&&amount>c.depositExpected-c.depositReceived)throw new Error('La réception ne peut pas dépasser la caution attendue.');if(!receive&&amount>c.depositReceived-c.depositReturned)throw new Error('La restitution ne peut pas dépasser la caution détenue.');if(receive)c.depositReceived+=amount;else c.depositReturned+=amount;c.depositLog.push({date:today,kind:s('kind'),amount});
 }else if(modal.kind==='departure'||modal.kind==='return'){
 const c=next.contracts.find(x=>x.id===modal.id)!;const v=next.cars.find(x=>x.id===c.carId)!;const image=await photoRead(f.get('photo'));const inspection:Inspection={date:s('date'),km:n('km'),fuel:s('fuel'),notes:s('notes'),photos:image?[image]:[]};if(!inspection.date)throw new Error('Renseignez la date et l’heure réelles.');if(new Date(inspection.date).getTime()>Date.now()+60000)throw new Error('La date réelle ne peut pas être dans le futur.');if(modal.kind==='departure'){
 if(c.status!=='préparé')throw new Error('Ce contrat ne peut pas partir.');if(inspection.km<v.km)throw new Error('Le kilométrage doit être au moins celui du véhicule.');const conflict=availability(data,c.carId,inspection.date,c.end,c.id);if(conflict)throw new Error(conflict);if(next.contracts.some(x=>x.carId===c.carId&&x.status==='en cours'))throw new Error('Un autre contrat est encore en cours pour cette voiture.');c.departure=inspection;c.status='en cours';v.km=inspection.km;v.status='louée';
 }else{
 if(c.status!=='en cours')throw new Error('Ce contrat n’est pas en cours.');const err=returnError(c,inspection.km,inspection.date);if(err)throw new Error(err);const amount=n('feeAmount');if(amount>0){if(invoiceFor(c.id))throw new Error('Une facture existe déjà. Aucun frais ne peut être ajouté à ce contrat.');if(!s('feeLabel'))throw new Error('Expliquez les frais supplémentaires.');c.fees.push({amount,label:s('feeLabel')})}if(s('carStatus')==='maintenance'&&(next.bookings.some(b=>b.carId===v.id&&b.status==='confirmée')||next.contracts.some(x=>x.carId===v.id&&x.id!==c.id&&['préparé','en cours'].includes(x.status))))throw new Error('Des réservations ou contrats futurs existent. Réaffectez-les ou annulez-les avant de placer la voiture en maintenance.');c.arrival=inspection;c.status='clôturé';v.km=inspection.km;v.status=s('carStatus') as Car['status'];}
 }else if(modal.kind==='maintenance'){
 const v=next.cars.find(x=>x.id===modal.id)!;v.maintenance.push({date:s('date'),label:s('label'),km:n('km'),amount:n('amount')});if(n('km')<v.km)throw new Error('Le kilométrage doit être au moins celui de la voiture.');v.km=n('km');v.oilDate=s('oilDate');v.oilKm=n('oilKm');
 }
 if(save(next)){const back=['payment','deposit','departure','return','contractEdit'].includes(modal.kind)?'contract':modal.kind==='maintenance'?'car':null;if(back)open(back,modal.id);else setModal(null)}
 }catch(e){setError((e as Error).message)}}
 function confirmAction(){if(!modal)return;const next=structuredClone(data);try{
 if(modal.kind==='reset'){if(save(seed(),'La démo a été réinitialisée.')){setFatal('');setModal(null);go('Tableau de bord')}return}
 if(modal.kind==='deleteCar'){if(data.contracts.some(c=>c.carId===modal.id)||data.bookings.some(b=>b.carId===modal.id))throw new Error('Cette voiture est liée à des locations. Sa suppression est bloquée pour préserver l’historique.');next.cars=next.cars.filter(c=>c.id!==modal.id)}
 if(modal.kind==='deleteClient'){if(data.contracts.some(c=>c.clientId===modal.id)||data.bookings.some(b=>b.clientId===modal.id))throw new Error('Ce client est lié à des locations. Sa suppression est bloquée pour préserver l’historique.');next.clients=next.clients.filter(c=>c.id!==modal.id)}
 if(modal.kind==='cancelBooking'){next.bookings.find(b=>b.id===modal.id)!.status='annulée'}
 if(modal.kind==='cancelContract'){const c=next.contracts.find(c=>c.id===modal.id)!;if(c.status!=='préparé'||paid(c)>0||c.depositReceived>c.depositReturned||invoiceFor(c.id))throw new Error('Seul un contrat préparé sans paiement, sans caution détenue et sans facture peut être annulé.');c.status='annulé'}
 if(save(next,'Action effectuée.'))setModal(null)
 }catch(e){setError((e as Error).message)}}
 function renderModal(){if(!modal)return null;const {kind,id}=modal;const c=id?data.contracts.find(x=>x.id===id):undefined;
 if(['reset','deleteCar','deleteClient','cancelBooking','cancelContract'].includes(kind))return <><p className="muted">{kind==='reset'?'Toutes vos modifications seront supprimées et remplacées par les données de démonstration. Cette action est irréversible.':kind.startsWith('delete')?'Confirmez-vous la suppression ? Les éléments liés à une location sont conservés pour protéger l’historique.':'Confirmez-vous l’annulation ? La voiture sera libérée pour les dates concernées.'}</p><div className="modal-actions"><button className="secondary" onClick={()=>setModal(null)}>Conserver</button><button className="danger-button" onClick={confirmAction}>Confirmer {kind==='reset'?'la réinitialisation':kind.startsWith('delete')?'la suppression':'l’annulation'}</button></div></>;
 if(kind.startsWith('pick')){const items=data.contracts.filter(c=>kind==='pickDeparture'?c.status==='préparé':kind==='pickReturn'?c.status==='en cours':c.status!=='annulé'&&balance(c)>0);return <div className="pick-list">{items.length?items.map(c=><button key={c.id} onClick={()=>open(kind==='pickDeparture'?'departure':kind==='pickReturn'?'return':'payment',c.id)}><span><b>{carName(car(c.carId))} · {clientName(client(c.clientId))}</b><small>{c.number} · {kind==='pickPayment'?money(balance(c))+' à payer':date(kind==='pickDeparture'?c.start:c.end,true)}</small></span><ArrowRight size={19}/></button>):<Empty text="Aucun contrat concerné pour le moment."/>}</div>}
 if(kind==='carForm'){const v=car(id??'');return <form onSubmit={submit}><div className="form-grid"><Field label="Marque" name="brand" value={v?.brand} required/><Field label="Modèle" name="model" value={v?.model} required/><Field label="Immatriculation" name="plate" value={v?.plate} required/><Field label="Année" name="year" type="number" min={1950} value={v?.year??new Date().getFullYear()} required/><Field label="Kilométrage" name="km" type="number" min={0} value={v?.km??0} required/><Field label="Tarif journalier (MAD)" name="rate" type="number" min={1} step="0.01" value={v?.rate??300} required/><Field label="Carburant" name="fuel" value={v?.fuel??'Diesel'} options={opts(['Diesel','Essence','Hybride','Électrique'])}/><Field label="Boîte de vitesses" name="gearbox" value={v?.gearbox??'Manuelle'} options={opts(['Manuelle','Automatique'])}/><Field label="État du véhicule" name="status" value={v?.status??'disponible'} options={opts(v&&statusOf(data,v)==='louée'?['louée']:['disponible','maintenance'])}/><Field label="Photo (1,5 Mo maximum)" name="photo" type="file"/><Field label="Échéance assurance" name="insurance" type="date" value={v?.insurance} required/><Field label="Échéance visite technique" name="inspection" type="date" value={v?.inspection} required/><Field label="Prochaine vidange (date)" name="oilDate" type="date" value={v?.oilDate}/><Field label="Prochaine vidange (km, 0 si inconnu)" name="oilKm" type="number" min={0} value={v?.oilKm??0}/></div><FormActions close={()=>setModal(null)}/></form>}
 if(kind==='clientForm')return <ClientForm client={client(id??'')} submit={submit} close={()=>setModal(null)}/>;
 if(kind==='bookingForm'||kind==='contractForm')return <BookingForm data={data} booking={data.bookings.find(b=>b.id===id)} direct={kind==='contractForm'} submit={submit} close={()=>setModal(null)}/>;
 if(kind==='car'){const v=car(id!)!;return <><div className="modal-actions" style={{marginTop:0}}><Badge>{statusOf(data,v)}</Badge><button className="secondary" onClick={()=>open('carForm',id)}><Pencil size={16}/>Modifier</button><button className="icon-button" title="Supprimer la voiture" onClick={()=>open('deleteCar',id)}><Trash2 size={18}/></button></div>{v.photo&&<div className="photos"><img src={v.photo} alt={carName(v)}/></div>}<div className="detail-grid"><Info label="Véhicule" value={`${carName(v)} · ${v.year}`}/><Info label="Immatriculation" value={v.plate}/><Info label="Kilométrage / carburant / boîte" value={`${v.km.toLocaleString('fr-FR')} km · ${v.fuel} · ${v.gearbox}`}/><Info label="Tarif journalier" value={money(v.rate)}/><Info label="Assurance / visite technique" value={`${date(v.insurance)} / ${date(v.inspection)}`}/><Info label="Prochaine vidange" value={`${date(v.oilDate)} · ${v.oilKm?v.oilKm.toLocaleString('fr-FR')+' km':'Km non renseigné'}`}/></div><h3>Historique des locations</h3>{table(['Contrat','Voiture','Période','Statut','Montant',''],data.contracts.filter(c=>c.carId===id).map(rentalRow))}<h3>Historique des entretiens</h3>{table(['Date','Intervention','Kilométrage','Coût'],v.maintenance.map((m,i)=><tr key={i}><td>{date(m.date)}</td><td>{m.label}</td><td>{m.km} km</td><td>{money(m.amount)}</td></tr>))}<div className="modal-actions"><button className="secondary" onClick={()=>open('maintenance',id)}><Plus size={17}/>Enregistrer un entretien</button></div></>}
 if(kind==='client'){const cl=client(id!)!;return <><div className="modal-actions" style={{marginTop:0}}><Badge>{cl.type}</Badge><button className="secondary" onClick={()=>open('clientForm',id)}><Pencil size={16}/>Modifier</button><button className="icon-button" title="Supprimer le client" onClick={()=>open('deleteClient',id)}><Trash2 size={18}/></button></div><div className="detail-grid"><Info label="Client" value={clientName(cl)}/><Info label="Téléphone / email" value={`${cl.phone} · ${cl.email||'Email non renseigné'}`}/><Info label="Adresse" value={cl.address}/>{cl.type==='entreprise'&&<Info label="ICE / contact" value={`${cl.ice} · ${cl.contact}`}/>}<Info label="Conducteur / pièce d’identité" value={`${cl.first} ${cl.last} · ${cl.identity}`}/><Info label="Permis / expiration" value={`${cl.license} · ${date(cl.licenseExpiry)}`}/><Info label="Reste à payer" value={money(active.filter(c=>c.clientId===id).reduce((s,c)=>s+balance(c),0))}/></div><h3>Historique des locations</h3>{table(['Contrat','Voiture','Période','Statut','Montant',''],data.contracts.filter(c=>c.clientId===id).map(rentalRow))}<h3>Réservations</h3>{bookingRows(data.bookings.filter(b=>b.clientId===id))}</>}
 if(kind==='booking'){const b=data.bookings.find(x=>x.id===id)!;return <><Badge>{b.status}</Badge><div className="detail-grid"><Info label="Client" value={clientName(client(b.clientId))}/><Info label="Voiture" value={`${carName(car(b.carId))} · ${car(b.carId)?.plate}`}/><Info label="Départ" value={date(b.start,true)}/><Info label="Retour" value={date(b.end,true)}/></div><div className="summary-strip"><div><small>Journées facturées</small><b>{days(b.start,b.end)}</b></div><div><small>Tarif / jour</small><b>{money(b.rate)}</b></div><div><small>Total</small><b>{money(days(b.start,b.end)*b.rate)}</b></div></div><p className="muted">Chaque tranche de 24 heures commencée compte comme une journée, minimum 1 jour.</p><div className="modal-actions">{b.status==='confirmée'?<><button className="secondary" onClick={()=>open('bookingForm',id)}><Pencil size={16}/>Modifier</button><button className="danger-button" onClick={()=>open('cancelBooking',id)}>Annuler</button><button className="primary" onClick={()=>convert(b)}>Créer le contrat <ArrowRight size={17}/></button></>:b.status==='convertie en contrat'?<button className="primary" onClick={()=>open('contract',data.contracts.find(c=>c.bookingId===id)?.id)}>Ouvrir le contrat</button>:null}</div></>}
 if(kind==='contract'&&c){const inv=invoiceFor(c.id);return <><div className="contract-top"><Badge>{c.status}</Badge><span className="muted"> {c.number}</span></div><div className="detail-grid"><Info label="Client / conducteur" value={`${clientName(client(c.clientId))} · ${c.driver}`}/><Info label="Voiture" value={`${carName(car(c.carId))} · ${car(c.carId)?.plate}`}/><Info label="Départ prévu" value={date(c.start,true)}/><Info label="Retour prévu" value={date(c.end,true)}/></div><p className="muted">{days(c.start,c.end)} jours × {money(c.rate)}{c.discount>0?` − ${money(c.discount)} de remise`:''}{c.tax>0?` · TVA configurée : ${c.tax} %`:''}</p><div className="summary-strip"><div><small>Total location</small><b>{money(total(c))}</b></div><div><small>Payé</small><b>{money(paid(c))}</b></div><div><small>Reste à payer</small><b className="remaining">{money(balance(c))}</b></div></div>{inv&&<div className="info-line"><Receipt size={17}/>Facture {inv.number} émise. Les montants sont verrouillés ; les paiements restent possibles.</div>}<div className="modal-actions" style={{marginTop:12}}>{c.status==='préparé'&&<button className="primary" onClick={()=>open('departure',id)}><ArrowUpRight size={17}/>Départ véhicule</button>}{c.status==='en cours'&&<button className="primary" onClick={()=>open('return',id)}><RotateCcw size={17}/>Retour véhicule</button>}{c.status!=='annulé'&&balance(c)>0&&<button className="secondary" onClick={()=>open('payment',id)}><Plus size={17}/>Ajouter un paiement</button>}<button className="secondary" onClick={()=>print(c)}><Printer size={17}/>Imprimer / PDF</button>{c.status!=='annulé'&&<button className="secondary" onClick={()=>generate(c)}><Receipt size={17}/>{inv?'Ouvrir la facture':'Générer une facture'}</button>}</div><h3>Paiements de location</h3>{table(['Date','Mode','Référence','Montant'],c.payments.map(p=><tr key={p.id}><td>{date(p.date)}</td><td>{p.mode}</td><td>{p.reference||'—'}</td><td>{money(p.amount)}</td></tr>))}<h3>Caution · hors chiffre d’affaires</h3><div className="summary-strip"><div><small>Attendue</small><b>{money(c.depositExpected)}</b></div><div><small>Reçue</small><b>{money(c.depositReceived)}</b></div><div><small>Restituée</small><b>{money(c.depositReturned)}</b></div></div>{(c.status!=='annulé'||c.depositReceived>c.depositReturned)&&<button className="secondary" onClick={()=>open('deposit',id)}>Réception / restitution de caution</button>}{c.depositLog.length>0&&table(['Date','Opération','Montant'],c.depositLog.map((p,i)=><tr key={i}><td>{date(p.date)}</td><td>{p.kind}</td><td>{money(p.amount)}</td></tr>))}{c.fees.length>0&&<><h3>Frais justifiés</h3>{table(['Libellé','Montant'],c.fees.map((f,i)=><tr key={i}><td>{f.label}</td><td>{money(f.amount)}</td></tr>))}</>}{[c.departure,c.arrival].map((item,i)=>item&&<div key={i}><h3>{i===0?'État au départ':'État au retour'}</h3><p className="muted">{date(item.date,true)} · {item.km} km · Carburant : {item.fuel}</p><p className="muted">{item.notes||'Aucune observation.'}</p><div className="photos">{item.photos.map((src,j)=><img key={j} src={src} alt={`État ${i?'au retour':'au départ'} ${j+1}`}/>)}</div></div>)}<h3>Observations et conditions</h3><p className="muted">{c.notes||'Aucune observation.'}</p><p className="muted">{c.conditions}</p>{c.status==='préparé'&&!inv&&<div className="modal-actions"><button className="secondary" onClick={()=>open('contractEdit',id)}>Modifier tarif, remise et caution</button><button className="danger-button" onClick={()=>open('cancelContract',id)}>Annuler le contrat</button></div>}</>}
 if(kind==='invoice'){const inv=data.invoices.find(x=>x.id===id)!;const linked=contract(inv.contractId);return <><div className="modal-actions" style={{margin:'0 0 25px'}}><button className="primary" onClick={()=>print(linked,inv)}><Printer size={17}/>Imprimer / Enregistrer en PDF</button><button className="secondary" onClick={()=>open('contract',linked.id)}>Voir le contrat lié</button>{balance(linked)>0&&<button className="secondary" onClick={()=>open('payment',linked.id)}>Ajouter un paiement</button>}</div><Document data={data} contract={linked} invoice={inv}/></>}
 if(kind==='contractEdit'&&c)return <form onSubmit={submit}><div className="form-grid"><Field label="Tarif journalier (MAD)" name="rate" type="number" min={0.01} step="0.01" value={c.rate} required/><Field label="Remise (MAD)" name="discount" type="number" min={0} step="0.01" value={c.discount}/><Field label="Caution attendue (MAD)" name="depositExpected" type="number" min={0} step="0.01" value={c.depositExpected}/><Field label="Conducteur" name="driver" value={c.driver} required/></div><Field label="Observations" name="notes" value={c.notes} type="textarea"/><FormActions close={()=>open('contract',id)}/></form>;
 if(kind==='payment'&&c)return <form onSubmit={submit}><div className="info-line">Solde restant : <b>{money(balance(c))}</b></div><div className="form-grid"><Field label="Montant (MAD)" name="amount" type="number" min={0.01} step="0.01" value={balance(c)} required/><Field label="Date du paiement" name="date" type="date" value={today} required/><Field label="Mode de paiement" name="mode" options={opts(['Espèces','Virement','Carte','Chèque'])}/><Field label="Référence (facultative)" name="reference"/></div><FormActions close={()=>open('contract',id)} label="Enregistrer le paiement"/></form>;
 if(kind==='deposit'&&c)return <form onSubmit={submit}><div className="info-line">À recevoir : {money(c.depositExpected-c.depositReceived)} · Détenue : {money(c.depositReceived-c.depositReturned)}</div><Field label="Opération" name="kind" value={c.depositReceived>=c.depositExpected?'Restitution':'Réception'} options={opts(['Réception','Restitution'])}/><Field label="Montant (MAD)" name="amount" type="number" min={0.01} step="0.01" required/><p className="muted">Ce mouvement de caution n’entre pas dans les encaissements de location.</p><FormActions close={()=>open('contract',id)}/></form>;
 if((kind==='departure'||kind==='return')&&c){const returning=kind==='return';return <form onSubmit={submit}><div className="info-line">{carName(car(c.carId))} · {clientName(client(c.clientId))}</div><div className="form-grid"><Field label={`Date et heure réelles ${returning?'du retour':'du départ'}`} name="date" type="datetime-local" value={relative(0,new Date().getHours())} required/><Field label="Kilométrage relevé" name="km" type="number" min={returning?c.departure?.km??0:car(c.carId)?.km??0} value={returning?c.departure?.km:car(c.carId)?.km} required/><Field label="Niveau de carburant" name="fuel" value="Plein" options={opts(['Plein','3/4','1/2','1/4','Réserve'])}/><Field label="Photo de l’état (facultative, 1,5 Mo max)" name="photo" type="file"/></div><Field label={returning?'Observations et dommages éventuels':'Observations sur l’état du véhicule'} name="notes" type="textarea"/>{returning&&<>{invoiceFor(c.id)?<div className="alert">Une facture existe déjà : les frais et le total sont verrouillés. Le retour clôture le contrat sans modifier les montants facturés. Les avoirs et factures complémentaires ne sont pas gérés dans cette démo.</div>:<><h3>Frais supplémentaires, si nécessaire</h3><p className="muted">Les retards ne sont pas facturés automatiquement. Ajoutez ici des frais justifiés avant de générer la facture.</p><div className="form-grid"><Field label="Libellé / justification" name="feeLabel"/><Field label="Montant des frais (MAD)" name="feeAmount" type="number" min={0} step="0.01" value={0}/></div></>}<Field label="État du véhicule après retour" name="carStatus" options={opts(['disponible','maintenance'])}/></>}<FormActions close={()=>open('contract',id)} label={returning?'Clôturer le contrat':'Confirmer le départ'}/></form>}
 if(kind==='maintenance'){const v=car(id!)!;return <form onSubmit={submit}><div className="form-grid"><Field label="Date de l’entretien" name="date" type="date" value={today} required/><Field label="Kilométrage" name="km" type="number" min={v.km} value={v.km} required/><Field label="Intervention effectuée" name="label" required/><Field label="Coût (MAD)" name="amount" type="number" min={0} step="0.01" value={0}/><Field label="Prochaine vidange (date)" name="oilDate" type="date" value={v.oilDate}/><Field label="Prochaine vidange (km)" name="oilKm" type="number" min={0} value={v.oilKm}/></div><FormActions close={()=>open('car',id)}/></form>}
 return null;
 }
}
function opts(items:string[]){return items.map(x=>({value:x,label:x}))}
function Info({label,value}:{label:string;value:string}){return <div><small>{label}</small><strong>{value}</strong></div>}
function FormActions({close,label='Enregistrer'}:{close:()=>void;label?:string}){return <div className="modal-actions"><button type="button" className="secondary" onClick={close}>Annuler</button><button type="submit" className="primary"><Check size={17}/>{label}</button></div>}
function modalTitle(m:NonNullable<Modal>){return ({car:'Fiche véhicule',carForm:m.id?'Modifier la voiture':'Ajouter une voiture',client:'Fiche client',clientForm:m.id?'Modifier le client':'Ajouter un client',booking:'Détail de la réservation',bookingForm:m.id?'Modifier la réservation':'Nouvelle réservation',contract:'Contrat de location',contractForm:'Nouveau contrat',contractEdit:'Modifier le contrat',invoice:'Facture de location',payment:'Ajouter un paiement',deposit:'Suivi de la caution',departure:'Départ véhicule',return:'Retour véhicule',maintenance:'Enregistrer un entretien',pickDeparture:'Choisir le contrat à démarrer',pickReturn:'Choisir le véhicule de retour',pickPayment:'Choisir la location à régler',reset:'Réinitialiser la démo ?',deleteCar:'Supprimer cette voiture ?',deleteClient:'Supprimer ce client ?',cancelBooking:'Annuler cette réservation ?',cancelContract:'Annuler ce contrat ?'} as Record<string,string>)[m.kind]??'Détails'}
function ClientForm({client:c,submit,close}:{client?:Client;submit:(e:FormEvent<HTMLFormElement>)=>void;close:()=>void}){const [type,setType]=useState(c?.type??'particulier');return <form onSubmit={submit}><label className="field"><span>Type de client</span><select name="type" value={type} onChange={e=>setType(e.target.value as Client['type'])}><option value="particulier">Particulier</option><option value="entreprise">Entreprise</option></select></label>{type==='entreprise'&&<div className="form-grid"><Field label="Raison sociale" name="company" value={c?.company} required/><Field label="ICE (15 chiffres)" name="ice" value={c?.ice} required/><Field label="Contact de l’entreprise" name="contact" value={c?.contact} required/></div>}{type==='entreprise'&&<h3>Informations du conducteur</h3>}<div className="form-grid"><Field label="Prénom" name="first" value={c?.first} required/><Field label="Nom" name="last" value={c?.last} required/><Field label="Téléphone" name="phone" type="tel" value={c?.phone} required/><Field label="Email" name="email" type="email" value={c?.email}/><Field label="CIN ou passeport" name="identity" value={c?.identity} required/><Field label="Numéro du permis" name="license" value={c?.license} required/><Field label="Expiration du permis" name="licenseExpiry" type="date" value={c?.licenseExpiry} required/><Field label="Adresse" name="address" value={c?.address} required/></div><FormActions close={close}/></form>}
function BookingForm({data,booking:b,direct,submit,close}:{data:Data;booking?:Booking;direct:boolean;submit:(e:FormEvent<HTMLFormElement>)=>void;close:()=>void}){
 const [carId,setCarId]=useState(b?.carId??data.cars.find(c=>c.status!=='maintenance')?.id??'');const [start,setStart]=useState(b?.start??relative(0,10));const [end,setEnd]=useState(b?.end??relative(1,10));const [rate,setRate]=useState(b?.rate??data.cars.find(c=>c.id===carId)?.rate??0);const [discount,setDiscount]=useState(0);const err=availability(data,carId,start,end,b?.id);const count=days(start,end);return <form onSubmit={submit}><Field label="Client" name="clientId" value={b?.clientId??''} required options={[{value:'',label:'Choisir un client'},...data.clients.map(c=>({value:c.id,label:clientName(c)}))]}/><div className="form-grid"><label className="field"><span>Date et heure de départ *</span><input type="datetime-local" name="start" value={start} onInput={e=>setStart(e.currentTarget.value)} required/></label><label className="field"><span>Date et heure de retour *</span><input type="datetime-local" name="end" value={end} onInput={e=>setEnd(e.currentTarget.value)} required/></label></div><label className="field"><span>Voiture *</span><select name="carId" value={carId} onChange={e=>{setCarId(e.target.value);setRate(data.cars.find(c=>c.id===e.target.value)?.rate??0)}} required>{data.cars.map(c=><option key={c.id} value={c.id}>{carName(c)} · {c.plate}{availability(data,c.id,start,end,b?.id)?' — indisponible':' — disponible'}</option>)}</select></label><div className="form-grid"><label className="field"><span>Tarif journalier (MAD) *</span><input name="rate" type="number" min="0.01" step="0.01" value={rate} onChange={e=>setRate(Number(e.target.value))} required/></label>{direct&&<label className="field"><span>Remise (MAD)</span><input name="discount" type="number" min="0" step="0.01" value={discount} onChange={e=>setDiscount(Number(e.target.value))}/></label>}</div>{direct&&<><div className="form-grid"><Field label="Caution attendue (MAD)" name="depositExpected" type="number" min={0} step="0.01" value={3000}/><Field label="Conducteur (vide = conducteur du client)" name="driver"/></div><Field label="Observations" name="notes" type="textarea"/></>}<div className="summary-strip"><div><small>Journées facturées</small><b>{Number.isFinite(count)?count:'—'}</b></div><div><small>Total {direct&&data.agency.taxEnabled?`(TVA ${data.agency.taxRate} % incluse)`:''}</small><b>{Number.isFinite(count)?money(Math.max(0,count*rate-discount)*(direct&&data.agency.taxEnabled?1+data.agency.taxRate/100:1)):'—'}</b></div></div><p className="muted">Chaque tranche de 24 heures commencée compte comme une journée, avec un minimum d’une journée.</p>{err&&<div className="alert danger" role="alert">{err}</div>}<FormActions close={close} label={direct?'Créer le contrat':'Confirmer la réservation'}/></form>
}
function Calendar({month,setMonth,data,query,open}:{month:Date;setMonth:(d:Date)=>void;data:Data;query:string;open:(kind:string,id:string)=>void}){const year=month.getFullYear(),m=month.getMonth();const first=new Date(year,m,1);const offset=(first.getDay()+6)%7;const count=new Date(year,m+1,0).getDate();const entries=[...data.bookings.filter(b=>b.status==='confirmée').map(b=>({...b,kind:'booking'})),...data.contracts.filter(c=>['préparé','en cours'].includes(c.status)).map(c=>({...c,kind:'contract'}))].filter(x=>`${carName(data.cars.find(c=>c.id===x.carId))} ${clientName(data.clients.find(c=>c.id===x.clientId))}`.toLowerCase().includes(query.toLowerCase()));return <section className="panel"><div className="calendar-header"><button className="icon-button" aria-label="Mois précédent" onClick={()=>setMonth(new Date(year,m-1,1))}><ChevronLeft/></button><h2>{new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric'}).format(month)}</h2><button className="icon-button" aria-label="Mois suivant" onClick={()=>setMonth(new Date(year,m+1,1))}><ChevronRight/></button></div><div className="calendar-grid">{['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(d=><div className="weekday" key={d}>{d}</div>)}{Array.from({length:Math.ceil((offset+count)/7)*7},(_,i)=>{const day=i-offset+1;const d=localDate(new Date(year,m,day));return <div className={`calendar-cell ${d===localDate()?'today':''}`} key={i}>{day>0&&day<=count&&<><span>{day}</span>{entries.filter(x=>x.start.slice(0,10)<=d&&x.end.slice(0,10)>=d).map(x=><button className={x.kind==='contract'?'contract-event':''} key={x.id} title={`${clientName(data.clients.find(c=>c.id===x.clientId))} · ${carName(data.cars.find(c=>c.id===x.carId))}`} onClick={()=>open(x.kind,x.id)}>{carName(data.cars.find(c=>c.id===x.carId))}</button>)}</>}</div>})}</div><p className="muted" style={{padding:15}}>Vert : réservations · Bleu : contrats préparés ou en cours.</p></section>}
function Document({data,contract:live,invoice:inv}:{data:Data;contract:Contract;invoice?:Invoice}){const c=inv?.contract??live;const agency=inv?.agency??data.agency;const cl=inv?.client??data.clients.find(x=>x.id===c.clientId)!;const v=inv?.car??data.cars.find(x=>x.id===c.carId)!;return <article className="document"><header className="doc-header"><div>{agency.logo&&<img src={agency.logo} alt="Logo agence"/>}<h3>{agency.name.trim()||'Gestion Location Auto'}</h3><p>{agency.address}<br/>{agency.phone} · {agency.email}{agency.ice&&<><br/>ICE : {agency.ice}</>}</p></div><div><h2>{inv?'FACTURE':'CONTRAT DE LOCATION'}</h2><p>{inv?.number??c.number}<br/>{inv?`Date : ${date(inv.date)}`:`Statut : ${live.status}`}{inv&&<><br/>Référence : {c.number}</>}</p></div></header><p className="doc-tag">DOCUMENT DE DÉMONSTRATION · NON VALIDÉ FISCALEMENT</p><div className="doc-parties"><div><h3>Client {cl.type==='entreprise'?'entreprise':''}</h3><p><b>{clientName(cl)}</b><br/>{cl.address}<br/>{cl.phone} · {cl.email}{cl.type==='entreprise'&&<><br/>ICE : {cl.ice}<br/>Contact : {cl.contact}</>}<br/>Conducteur : {c.driver}<br/>CIN / passeport : {cl.identity}<br/>Permis : {cl.license} · Exp. {date(cl.licenseExpiry)}</p></div><div><h3>Véhicule et période</h3><p><b>{carName(v)}</b><br/>Immatriculation : {v.plate}<br/>{v.year} · {v.fuel} · {v.gearbox}<br/>Départ : {date(c.start,true)}<br/>Retour prévu : {date(c.end,true)}</p></div></div><table><thead><tr><th>Désignation</th><th>Quantité</th><th>Prix unitaire</th><th>Montant</th></tr></thead><tbody><tr><td>Location {carName(v)}</td><td>{days(c.start,c.end)} jours</td><td>{money(c.rate)}</td><td>{money(days(c.start,c.end)*c.rate)}</td></tr>{c.fees.map((f,i)=><tr key={i}><td>{f.label}</td><td>1</td><td>{money(f.amount)}</td><td>{money(f.amount)}</td></tr>)}</tbody></table><div className="doc-totals">{c.discount>0&&<div><span>Remise</span><b>− {money(c.discount)}</b></div>}{c.tax>0&&<><div><span>Total avant TVA</span><b>{money(subtotal(c))}</b></div><div><span>TVA configurée ({c.tax} %)</span><b>{money(total(c)-subtotal(c))}</b></div></>}<div><span>Total</span><b>{money(total(c))}</b></div><div><span>Montant payé</span><b>{money(paid(live))}</b></div><div><span>Reste à payer</span><b>{money(total(c)-paid(live))}</b></div></div>{c.tax===0&&<p className="doc-tag">TVA non appliquée dans cette démonstration ; aucun régime fiscal n’est présumé.</p>}<p className="muted">Tarification : chaque tranche de 24 heures commencée compte comme une journée, minimum une journée.</p>{!inv&&<><h3 style={{marginTop:20}}>Caution suivie séparément</h3><p>Attendue : {money(live.depositExpected)} · Reçue : {money(live.depositReceived)} · Restituée : {money(live.depositReturned)}</p>{live.departure&&<p>Départ réel : {date(live.departure.date,true)} · {live.departure.km} km · {live.departure.fuel} · {live.departure.notes}</p>}{live.arrival&&<p>Retour réel : {date(live.arrival.date,true)} · {live.arrival.km} km · {live.arrival.fuel} · {live.arrival.notes}</p>}<h3 style={{marginTop:20}}>Conditions de démonstration</h3><p>{c.conditions}</p>{c.notes&&<p>Observations : {c.notes}</p>}<div className="doc-signatures"><div>Signature de l’agence</div><div>Signature du client / conducteur</div></div></>}<p className="muted" style={{marginTop:20}}>{inv?agency.conditions:""}</p><p className="doc-tag" style={{marginTop:25}}>Document fictif établi pour la présentation du prototype. Paiements actualisés au {date(localDate())}.</p></article>}
